package mapper;import entity.PhieuThu;import java.sql.ResultSet;import java.sql.SQLException;import java.time.LocalDate;import java.time.LocalDateTime;public class PhieuThuMapper implements RowMapper<PhieuThu> {    @Override    public PhieuThu mapper(ResultSet rs) {        try {            String maPhieuThu = rs.getString("maPhieuThu");            LocalDate ngayThu = Rs.date(rs, "ngayThu");            String maKH = rs.getString("maKH");            String maHoaDon = rs.getString("maHoaDon");            String lyDo = rs.getString("lyDo");            long soTien = rs.getLong("soTien");            String hinhThucThanhToan = rs.getString("hinhThucThanhToan");            String trangThai = rs.getString("trangThai");            String maBacSi = rs.getString("maBacSi");            String maPhuTa = rs.getString("maPhuTa");            String nguoiGioiThieu = rs.getString("nguoiGioiThieu");            LocalDateTime ngayTao = Rs.dateTime(rs, "ngayTao");            String nguoiTao = rs.getString("nguoiTao");            return new PhieuThu(maPhieuThu, ngayThu, maKH, maHoaDon, lyDo, soTien, hinhThucThanhToan, trangThai, maBacSi, maPhuTa, nguoiGioiThieu, ngayTao, nguoiTao);        } catch (SQLException e) {            return null;        }    }}